  "Website / App Development",
  "Branding & Identity",
  "Social Media Marketing",
  "YouTube Monetization",
  "Photography & Shoots",
  "Music Production",
  "SEO & Digital Campaigns",
  "Full Media Package",
  "Other / Custom Project",
