                    className="w-full py-5 px-8 rounded-2xl bg-white/[0.03] border border-white/[0.08] backdrop-blur-sm text-white font-bold text-xs uppercase tracking-[0.25em] flex items-center justify-center gap-3 transition-all duration-500 hover:bg-accent-green hover:text-black hover:border-accent-green hover:shadow-[0_0_50px_rgba(0,217,95,0.35)] group/btn cursor-pointer"
